mapper.select:
select t.id, t.title, t.cover_image as coverImage, t.start_date as startDate, t.end_date as endDate, t.people_count as peopleCount, t.budget, t.travel_type as travelType, t.source, t.status, c.name as cityName, u.nickname, u.avatar_url as avatarUrl, (select count(*) from voya_ai_trip_day d where d.trip_id = t.id and d.del_flag = '0') as dayCount, t.create_time as createTime from voya_ai_trip t left join voya_ai_city c on t.city_id = c.id left join voya_ai_user u on t.user_id = u.id
t.del_flag = '0'
and t.city_id = #{cityId}
and t.title like concat('%', #{keyword}, '%')
and t.source = #{source}
and t.create_time >= #{beginCreateTime}
and t.create_time < date_add(#{endCreateTime}, interval 1 day)
order by t.id desc
